¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚Â

export function getPraveshOffset(planet: Planet, praveshData: any, w: NDSWeights): { score: number, conditions: AppliedCondition[] } {
  if (w.disabledParams?.disableModule6) return { score: 0, conditions: [] };
  if (!praveshData) return { score: 0, conditions: [] };
  
  let score = 0;
  const conditions: AppliedCondition[] = [];

  let hScore = 0;
  let hKey: keyof NDSWeights = 'praveshHouse1';
  switch (praveshData.house) {
    case 1: hScore = w.praveshHouse1; hKey = 'praveshHouse1'; break;
    case 2: hScore = w.praveshHouse2; hKey = 'praveshHouse2'; break;
    case 3: hScore = w.praveshHouse3; hKey = 'praveshHouse3'; break;
    case 4: hScore = w.praveshHouse4; hKey = 'praveshHouse4'; break;
    case 5: hScore = w.praveshHouse5; hKey = 'praveshHouse5'; break;
    case 6: hScore = w.praveshHouse6; hKey = 'praveshHouse6'; break;
    case 7: hScore = w.praveshHouse7; hKey = 'praveshHouse7'; break;
    case 8: hScore = w.praveshHouse8; hKey = 'praveshHouse8'; break;
    case 9: hScore = w.praveshHouse9; hKey = 'praveshHouse9'; break;
    case 10: hScore = w.praveshHouse10; hKey = 'praveshHouse10'; break;
    case 11: hScore = w.praveshHouse11; hKey = 'praveshHouse11'; break;
    case 12: hScore = w.praveshHouse12; hKey = 'praveshHouse12'; break;
  }
  
  if (hScore !== 0) {
    score += hScore;
    conditions.push({ key: hKey, name: `Dasha Pravesh in House ${praveshData.house}`, value: hScore });
  }
  
  const rasiName = praveshData.rasi.name as Sign;
  if (isExalted(planet, rasiName)) {
    score += w.praveshExalted;
    conditions.push({ key: 'praveshExalted', name: 'Dasha Pravesh Exalted', value: w.praveshExalted });
  } else if (isDebilitated(planet, rasiName)) {
    score += w.praveshDebilitated;
    conditions.push({ key: 'praveshDebilitated', name: 'Dasha Pravesh Debilitated', value: w.praveshDebilitated });
  } else if (isOwnSign(planet, rasiName)) {
    score += w.praveshOwnSign;
    conditions.push({ key: 'praveshOwnSign', name: 'Dasha Pravesh Own Sign', value: w.praveshOwnSign });
  }
  
  return { score, conditions };
}

function isConjunctWithoutPlanetBetween(p1Name: Planet, p2Name: Planet, positions: any[], maxDiff: number = 10): boolean {
  const p1 = positions.find(p => (p.planet || p.name) === p1Name);
  const p2 = positions.find(p => (p.planet || p.name) === p2Name);
  if (!p1 || !p2 || typeof p1.longitude !== 'number' || typeof p2.longitude !== 'number') return false;

  const lon1 = p1.longitude;
  const lon2 = p2.longitude;

  let diff = Math.abs(lon1 - lon2);
  if (diff > 180) diff = 360 - diff;
  if (diff > maxDiff) return false;

  // Check if any other planet is between them
  let min = Math.min(lon1, lon2);
  let max = Math.max(lon1, lon2);
  let crossesAries = (max - min > 180);

  if (crossesAries) {
    min = max;
    max = Math.min(lon1, lon2) + 360;
  }

  for (const pos of positions) {
    const name = pos.planet || pos.name;
    if (name === p1Name || name === p2Name) continue;
    if (['Ascendant', 'Lagna', 'Uranus', 'Neptune', 'Pluto'].includes(name)) continue;
    if (typeof pos.longitude !== 'number') continue;
    
    let l = pos.longitude;
    if (crossesAries && l < 60) l += 360;
    
    if (l > min && l < max) {
      return false; // Found a planet between them
    }
  }

  return true;
}

export function getAdvancedModifiers(planet: Planet, positions: any[], w: NDSWeights, dashaLevel?: 'MD' | 'AD' | 'PD', yogaState?: YogaState): { score: number, conditions: AppliedCondition[] } {
  if (w.disabledParams?.advancedRules) return { score: 0, conditions: [] };
  let score = 0;
  const conditions: AppliedCondition[] = [];

  // Taradasha specific tuning
  if (dashaLevel && w.taradashaMatrix) {
    const pIdx = PLANETS.indexOf(planet);
    const colIdx = dashaLevel === 'MD' ? 0 : dashaLevel === 'AD' ? 1 : 2;
    const tdScore = w.taradashaMatrix[pIdx]?.[colIdx] || 0;
    if (tdScore !== 0) {
      score += tdScore;
      conditions.push({ key: 'taradashaMatrix', name: `Taradasha Tuning (${dashaLevel})`, value: tdScore });
    }
  }

  const pPos = positions.find(p => (p.planet || p.name) === planet);
  const mPos = positions.find(p => (p.planet || p.name) === 'Moon');
  
  // Navtara points
  if (pPos?.nakshatra?.index !== undefined && mPos?.nakshatra?.index !== undefined && w.navtaraPoints) {
    const taraIdx = (pPos.nakshatra.index - mPos.nakshatra.index + 27) % 9;
    const taraScore = w.navtaraPoints[taraIdx] || 0;
    if (taraScore !== 0) {
      score += taraScore;
      const taraNames = ['Janma', 'Sampat', 'Vipat', 'Kshema', 'Pratyari', 'Sadhaka', 'Naidhana', 'Mitra', 'Ati Mitra'];
      conditions.push({ key: 'navtaraPoints', name: `Navtara (${taraNames[taraIdx]})`, value: taraScore });
    }
  }

  // Shastiamsa (D60) points
  if (pPos?.rasi?.degreesInSign !== undefined && pPos?.rasi?.index !== undefined) {
    const d60Nature = getD60Nature(pPos.rasi.index, pPos.rasi.degreesInSign);
    if (d60Nature === 'Benefic' && w.beneficShastiamsaPoints) {
      score += w.beneficShastiamsaPoints;
      conditions.push({ key: 'beneficShastiamsaPoints', name: 'Benefic Shastiamsa', value: w.beneficShastiamsaPoints });
    } else if (d60Nature === 'Malefic' && w.maleficShastiamsaPoints) {
      score += w.maleficShastiamsaPoints;
      conditions.push({ key: 'maleficShastiamsaPoints', name: 'Malefic Shastiamsa', value: w.maleficShastiamsaPoints });
    }
  }

  // Advanced Jup/Sat Conjunct Rule
  if ((planet === 'Jupiter' || planet === 'Saturn') && w.advancedJupSatConjunctPoints) {
    if (isConjunctWithoutPlanetBetween('Jupiter', 'Saturn', positions, 10)) {
      const pts = planet === 'Saturn' ? w.advancedJupSatConjunctPoints : -w.advancedJupSatConjunctPoints;
      score += pts;
      conditions.push({ key: 'advancedJupSatConjunctPoints', name: 'Jup/Sat Close Conjunction', value: pts });
    }
  }


  // Advanced Yamaghantak Dispositor Rule
  if (w.advancedYamaDispositorPoints) {
    const yama = positions.find(p => p.name === 'Yamaghantak');
    if (yama) {
      const ZODIAC_LORDS = ['Mars', 'Venus', 'Mercury', 'Moon', 'Sun', 'Mercury', 'Venus', 'Mars', 'Jupiter', 'Saturn', 'Saturn', 'Jupiter'];
      const signIdx = Math.floor(yama.longitude / 30);
      const disp = ZODIAC_LORDS[signIdx];
      if (planet === disp) {
        score += w.advancedYamaDispositorPoints;
        conditions.push({ key: 'advancedYamaDispositorPoints', name: 'Yamaghantak Dispositor', value: w.advancedYamaDispositorPoints });
      }
    }
  }

  // Advanced Gulika Dispositor Rule
  if (w.advancedGulikaDispositorPoints) {
    const gulika = positions.find(p => p.name === 'Gulika');
    if (gulika) {
      const ZODIAC_LORDS = ['Mars', 'Venus', 'Mercury', 'Moon', 'Sun', 'Mercury', 'Venus', 'Mars', 'Jupiter', 'Saturn', 'Saturn', 'Jupiter'];
      const signIdx = Math.floor(gulika.longitude / 30);
      const disp = ZODIAC_LORDS[signIdx];
      if (planet === disp) {
        score += w.advancedGulikaDispositorPoints;
        conditions.push({ key: 'advancedGulikaDispositorPoints', name: 'Gulika Dispositor', value: w.advancedGulikaDispositorPoints });
      }
    }
  }

  // Advanced 8th/9th Lord Rule
  if (yogaState && w.advanced8th9thLordPoints) {
    const lord8 = yogaState.houses[8].lord;
    const lord9 = yogaState.houses[9].lord;
    
    if (lord8 && lord9 && (planet === lord8 || planet === lord9)) {
      let applies = false;
      const h8Info = yogaState.planets[lord8];
      const h9Info = yogaState.planets[lord9];
      
      // Condition A: Close conjunction without planet between
      if (isConjunctWithoutPlanetBetween(lord8, lord9, positions, 10)) {
        applies = true;
      }
      // Condition B: Exchange Rasis (Parivartana Yoga)
      else if (h8Info.house === 9 && h9Info.house === 8) {
        applies = true;
      }
      // Condition C: Mutual Aspect
      else if (hasVedicAspect(lord8, h8Info.house, h9Info.house) && hasVedicAspect(lord9, h9Info.house, h8Info.house)) {
        applies = true;
      }

      if (applies) {
        const pts = planet === lord8 ? w.advanced8th9thLordPoints : -w.advanced8th9thLordPoints;
        score += pts;
        conditions.push({ key: 'advanced8th9thLordPoints', name: '8th/9th Lord Interaction', value: pts });
      }
    }
  }

  // 1. Rahu/Ketu Moon Conjunct
  const moonPos = positions.find(p => p.planet === 'Moon');
  const rahuPos = positions.find(p => p.planet === 'Rahu');
  const ketuPos = positions.find(p => p.planet === 'Ketu');
  
  if (planet === 'Moon' || planet === 'Rahu' || planet === 'Ketu') {
      if (moonPos && (rahuPos || ketuPos)) {
          if ((rahuPos && moonPos.sign === rahuPos.sign) || (ketuPos && moonPos.sign === ketuPos.sign)) {
              // Wait, penalty applies to what planet? To Moon, Rahu, Ketu?
              // The rule says penalty when Rahu/Ketu is conjunct Moon.
              const penalty = w.rahuKetuMoonConjunct || 0;
              score += penalty;
              conditions.push({ key: 'rahuKetuMoonConjunct', name: 'Moon conjunct Node (Rahu/Ketu)', value: penalty });
          }
      }
  }

  return { score, conditions };
}

