¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚Â


export function getNavamshaModifiers(planet: Planet, yogaState: YogaState, alSignIndex: number, w: NDSWeights): { score: number, conditions: AppliedCondition[] } {
  if (w.disabledParams?.disableModule7) return { score: 0, conditions: [] };
  let score = 0;
  const conditions: AppliedCondition[] = [];
  const info = yogaState.planets[planet];
  
  const navamshaSignName = info.position.navamsha.name as Sign;
  const navamshaSignIndex = info.position.navamsha.index;
  const rasiSignIndex = info.position.rasi.index;
  const navamshaLord = SIGN_LORDS[navamshaSignName];

  // 1. navamshaExaltedOwnAL: Exalted, Own Sign, Same as AL
  const isNavExalted = isExalted(planet, navamshaSignName);
  const isNavOwn = navamshaLord === planet;
  const isSameAsAL = navamshaSignIndex === alSignIndex;
  
  if (isNavExalted || isNavOwn || isSameAsAL) {
    score += w.navamshaExaltedOwnAL;
    conditions.push({ key: 'navamshaExaltedOwnAL', name: 'Navamsha Exalted/Own/AL', value: w.navamshaExaltedOwnAL });
  }

  // 2. navamsha5th9th: 5/9 from Rasi sign
  const distRasiToNav = (navamshaSignIndex - rasiSignIndex + 12) % 12 + 1;
  const is5or9 = distRasiToNav === 5 || distRasiToNav === 9;

  if (is5or9) {
    score += w.navamsha5th9th;
    conditions.push({ key: 'navamsha5th9th', name: 'Navamsha 5th/9th from Rasi', value: w.navamsha5th9th });
  }

  // 3. navamshaDebilitated: Debilitated unless with sign lord
  const isNavDebilitated = isDebilitated(planet, navamshaSignName);
  let isWithSignLord = false;
  if (isNavDebilitated && navamshaLord && yogaState.planets[navamshaLord]) {
    if (yogaState.planets[navamshaLord].position.navamsha.name === navamshaSignName) {
      isWithSignLord = true;
    }
  }

  if (isNavDebilitated && !isWithSignLord) {
    score += w.navamshaDebilitated;
    conditions.push({ key: 'navamshaDebilitated', name: 'Navamsha Debilitated', value: w.navamshaDebilitated });
  }

  // 4. navamsha6th8th12th: 6/8/12 from Rasi sign
  const is6812 = distRasiToNav === 6 || distRasiToNav === 8 || distRasiToNav === 12;

  if (is6812) {
    score += w.navamsha6th8th12th;
    conditions.push({ key: 'navamsha6th8th12th', name: 'Navamsha 6th/8th/12th from Rasi', value: w.navamsha6th8th12th });
  }

  // 3. Benefic / Malefic Navamsha
  const isBeneficLord = PLANET_NATURE[navamshaLord] === 'Benefic';
  if (isBeneficLord) {
    score += w.navamshaBenefic;
    conditions.push({ key: 'navamshaBenefic', name: 'Benefic Navamsha', value: w.navamshaBenefic });
  } else {
    score += w.navamshaMalefic;
    conditions.push({ key: 'navamshaMalefic', name: 'Malefic Navamsha', value: w.navamshaMalefic });
  }

  return { score, conditions };
}

export function calculateNDS(
  planet: Planet,
  yogaState: YogaState,
  positions: any[],
  alSignIndex: number,
  awasthasData: any,
  weights: NDSWeights,
  mdLord?: Planet,
  praveshData?: any,
  isDispositorCall: boolean = false,
  dashaLevel?: 'MD' | 'AD' | 'PD'
): NDSResult {
  const base = getBaseLordshipScore(planet, yogaState, weights);
  const dignity = getDignityScore(planet, yogaState, positions, weights);
  const mutual = mdLord && mdLord ? getMutualPlacement(mdLord, planet, yogaState, weights) : { score: 0, conditions: [] };
  const arudha = getArudhaModifiers(planet, yogaState, alSignIndex, weights);
  const navamsha = getNavamshaModifiers(planet, yogaState, alSignIndex, weights);
  const awastha = getAwasthaModifiers(planet, awasthasData, weights);
  const pravesh = getPraveshOffset(planet, praveshData, weights);
  const advanced = getAdvancedModifiers(planet, positions, weights, dashaLevel, yogaState);

  const allConditions = [
    ...base.conditions,
    ...dignity.conditions,
    ...mutual.conditions,
    ...arudha.conditions,
    ...navamsha.conditions,
    ...awastha.conditions,
    ...pravesh.conditions,
    ...advanced.conditions
  ].filter(c => c.value !== 0);

  let netScore = base.score + dignity.score + mutual.score + arudha.score + navamsha.score + awastha.score + pravesh.score + advanced.score;

  if (!isDispositorCall && (planet === 'Rahu' || planet === 'Ketu')) {
    const nodeHouse = yogaState.planets[planet].house;
    const dispositor = yogaState.houses[nodeHouse].lord;
    if (dispositor && dispositor !== 'Rahu' && dispositor !== 'Ketu') {
      const dispositorResult = calculateNDS(dispositor, yogaState, positions, alSignIndex, awasthasData, weights, mdLord, praveshData, true, dashaLevel);
      const addedScore = Math.round(dispositorResult.netScore * 0.5);
      allConditions.push({
        key: 'dispositorScore' as keyof NDSWeights,
        name: `50% of Dispositor (${dispositor}) Score`,
        value: addedScore
      });
      netScore += addedScore;
    }
  }

  const maxPossible = allConditions.reduce((sum, c) => sum + Math.abs(c.value), 0);
  
  let percentage = 0;
  if (maxPossible > 0) {
    percentage = Math.round((netScore / maxPossible) * 100);
  }

  return {
    percentage: clamp(percentage, -100, 100),
    netScore,
    maxPossible,
    conditions: allConditions,
    breakdown: {
      baseLordship: base.score,
      dignityScore: dignity.score,
      mutualPlacement: mutual.score,
      arudhaModifiers: arudha.score,
      navamshaModifiers: navamsha.score,
      awasthaModifiers: awastha.score,
      praveshOffset: pravesh.score,
      advancedRules: advanced.score,
    },
  };
}

