¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚Â

export function generateDashaTimeSeries(
  dashas: DashaPeriod[],
  yogaState: YogaState,
  positions: any[],
  alSignIndex: number,
  awasthasData: any,
  weights: NDSWeights = DEFAULT_NDS_WEIGHTS
): DashaTimePoint[] {
  const points: DashaTimePoint[] = [];

  for (const md of dashas) {
    const mdPlanet = md.planet as Planet;
    const mdResult = calculateNDS(mdPlanet, yogaState, positions, alSignIndex, awasthasData, weights, undefined, md.pravesh, false, 'MD');
    const adPeriods = md.subPeriods ?? [];

    for (const ad of adPeriods) {
      const adPlanet = ad.planet as Planet;
      const adResult = calculateNDS(adPlanet, yogaState, positions, alSignIndex, awasthasData, weights, mdPlanet, ad.pravesh, false, 'AD');

      // Fallback weights if missing
      const rawMdW = weights.mdWeightPercentage ?? 50;
      const rawAdW = weights.adWeightPercentage ?? 45;
      const rawPdW = weights.pdWeightPercentage ?? 5;
      
      // Normalize to ensure they sum to exactly 1.0 (in case of manual config drift)
      const totalW = rawMdW + rawAdW + rawPdW;
      const mdW = rawMdW / totalW;
      const adW = rawAdW / totalW;
      const pdW = rawPdW / totalW;
      
      const blendedAdPercentage = mdResult.percentage * mdW + adResult.percentage * adW;

      const pdPeriods = ad.subPeriods ?? [];
      
      // If there are no PDs (should not happen normally), fallback to AD
      if (pdPeriods.length === 0) {
        points.push({
          date: ad.start,
          mdPlanet,
          adPlanet,
          pdPlanet: '',
          // Assuming pdMatrixScore would be 50 (neutral) -> 0 * pdW = 0
          percentage: clamp(Math.round(blendedAdPercentage), -100, 100),
          mdPercentage: mdResult.percentage,
          adPercentage: adResult.percentage,
          mdResult,
          adResult
        });
        continue;
      }

      for (const pd of pdPeriods) {
        const pdPlanet = pd.planet as Planet;
        const pdMatrixScore = getPdAuspiciousness(adPlanet, pdPlanet);
        
        // Convert PD Matrix Score (1-100) to NDF scale (-100 to 100)
        // 50 becomes 0, 100 becomes +100, 0 becomes -100
        const pIdx = PLANETS.indexOf(pdPlanet);
          const tdPdScore = weights.taradashaMatrix?.[pIdx]?.[2] || 0;
          let pdPercentage = (pdMatrixScore - 50) * 2;
          pdPercentage += tdPdScore;
        
        const blendedPdPercentage = clamp(
          Math.round(blendedAdPercentage + (pdPercentage * pdW)),
          -100,
          100
        );

        points.push({
          date: pd.start,
          mdPlanet,
          adPlanet,
          pdPlanet,
          percentage: blendedPdPercentage,
          mdPercentage: mdResult.percentage,
          adPercentage: adResult.percentage,
          mdResult,
          adResult
        });
      }
    }
  }

  return points;
}

export function applyAsymptoticCap(score: number): number {
  if (Math.abs(score) <= 50) return score;
  const sign = Math.sign(score);
  const excess = Math.abs(score) - 50;
  // Soft scale: 50 + 50 * (1 - e^(-excess/50))
  // e.g. 50 -> 50
  // 100 -> 50 + 50*(1 - 0.367) = 81.6
  // 150 -> 50 + 50*(1 - 0.135) = 93.2
  const scaled = 50 + 50 * (1 - Math.exp(-excess / 50));
  return sign * scaled;
}











